SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_814
WHERE non_leaf_814.ci_person_id = pi.person_id AND (t.production_year >= 1990) AND (it2.id IN ('29')) AND (kt.kind IN ('episode','movie','tv mini series','tv series','video game','video movie')) AND it2.id = pi.info_type_id AND mi1.movie_id = non_leaf_814.ci_movie_id AND (it1.id IN ('8')) AND (mi1.info ILIKE '%cub%') AND non_leaf_814.n_id = pi.person_id AND it1.id = mi1.info_type_id AND (pi.info ILIKE '%wa%') AND (rt.role IN ('actor','cinematographer','composer','costume designer','producer')) AND ct.id = non_leaf_814.mc_company_type_id AND (t.production_year <= 2015) AND mi1.movie_id = non_leaf_814.t_id;